/* inventory_service.c - Legacy inventory management monolith
 * Handles bulk order processing for warehouse management system
 * Compiled with: gcc -o inventory_service inventory_service.c -lpthread
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_ITEMS 1000000
#define LISTEN_PORT 8080

struct order_item {
    uint32_t item_id;
    uint32_t quantity;
    uint32_t unit_price_cents;
};

struct bulk_order {
    uint32_t customer_id;
    uint32_t num_items;
    uint32_t discount_percent;
    struct order_item items[];
};

/* Calculate total allocation size for order processing buffer */
static size_t calculate_buffer_size(uint32_t num_items) {
    /* Each item needs 64 bytes for processing metadata */
    size_t per_item_size = 64;
    size_t total = num_items * per_item_size;  /* INTEGER OVERFLOW HERE */
    return total + sizeof(struct bulk_order);
}

/* Process incoming bulk order - reads binary protocol from socket */
static void process_bulk_order(int client_fd) {
    struct bulk_order header;
    ssize_t bytes_read;

    /* Read order header */
    bytes_read = read(client_fd, &header, sizeof(header));
    if (bytes_read != sizeof(header)) {
        write(client_fd, "ERR\n", 4);
        return;
    }

    /* Validate item count - but overflow happens in calculate_buffer_size */
    if (header.num_items == 0 || header.num_items > MAX_ITEMS) {
        write(client_fd, "ERR: invalid item count\n", 24);
        return;
    }

    /* Calculate and allocate processing buffer */
    size_t buf_size = calculate_buffer_size(header.num_items);

    /* On 32-bit systems or when num_items is large enough:
     * num_items=0x04000001, per_item_size=64 => 0x04000001*64 = 0x100000040
     * which truncates to 0x00000040 on 32-bit size_t, causing tiny allocation */
    char *processing_buf = (char *)malloc(buf_size);
    if (!processing_buf) {
        write(client_fd, "ERR: allocation failed\n", 23);
        return;
    }

    /* Copy header into buffer */
    memcpy(processing_buf, &header, sizeof(header));

    /* Read all items into buffer - HEAP OVERFLOW when buf_size was truncated */
    size_t items_data_size = header.num_items * sizeof(struct order_item);
    size_t total_read = 0;
    while (total_read < items_data_size) {
        bytes_read = read(client_fd, processing_buf + sizeof(header) + total_read,
                         items_data_size - total_read);
        if (bytes_read <= 0) break;
        total_read += bytes_read;
    }

    /* Process order totals */
    uint64_t total_cents = 0;
    struct order_item *items = (struct order_item *)(processing_buf + sizeof(header));
    for (uint32_t i = 0; i < header.num_items && i < (buf_size / sizeof(struct order_item)); i++) {
        total_cents += (uint64_t)items[i].quantity * items[i].unit_price_cents;
    }

    char response[128];
    snprintf(response, sizeof(response), "OK: total=%lu cents\n", total_cents);
    write(client_fd, response, strlen(response));

    free(processing_buf);
}

static void *handle_client(void *arg) {
    int client_fd = *(int *)arg;
    free(arg);
    process_bulk_order(client_fd);
    close(client_fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    int server_fd, *client_fd;
    struct sockaddr_in addr;
    pthread_t tid;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;  /* Binds all interfaces */
    addr.sin_port = htons(LISTEN_PORT);

    bind(server_fd, (struct sockaddr *)&addr, sizeof(addr));
    listen(server_fd, 128);

    printf("Inventory service listening on port %d\n", LISTEN_PORT);

    while (1) {
        client_fd = malloc(sizeof(int));
        *client_fd = accept(server_fd, NULL, NULL);
        if (*client_fd < 0) { free(client_fd); continue; }
        pthread_create(&tid, NULL, handle_client, client_fd);
        pthread_detach(tid);
    }
    return 0;
}
